var resultStr = String(result);

// ===== 播放地址提取：videoInitialData JSON 优先（2026-10-18 修复）=====
// 站点字段：videoSrc=当前集地址；epPlaySrcs[集号]=整部剧各集表（键"1"恒排最前，
// 旧版深搜无脑取第一个 → 每集都返回第 1 集，表现为"所有视频是同一个"）。
function pickM3u8(j, pageUrl){
  if (!j || typeof j !== 'object') return '';
  if (typeof j.videoSrc === 'string' && j.videoSrc.indexOf('.m3u8') >= 0) return j.videoSrc;
  var epn = 1;
  var em = String(pageUrl || '').match(/ep-(\d+)/);
  if (em) epn = parseInt(em[1], 10);
  if (j.epPlaySrcs && typeof j.epPlaySrcs === 'object') {
    var v = j.epPlaySrcs[epn] || j.epPlaySrcs[String(epn)];
    if (typeof v === 'string' && v.indexOf('.m3u8') >= 0) return v;
  }
  return '';
}
function extractM3u8FromHtml(h, pageUrl){
  h = String(h || '');
  var vm = h.match(/<script id="videoInitialData" type="application\/json">([\s\S]*?)<\/script>/);
  if (vm) {
    try {
      var j = JSON.parse(vm[1]);
      var u = pickM3u8(j, pageUrl) || deepFindM3u8(j, pageUrl);
      if (u) return u;
    } catch(e){}
  }
  var m = h.match(/<article class="hg-play__slide is-active"[^>]*data-play-src="([^"]*)"/);
  if (!m) m = h.match(/data-play-src="([^"]*)"/);
  if (m) return m[1].replace(/&amp;/g, '&').replace(/&quot;/g, '"');
  return '';
}
function deepFindM3u8(o, pageUrl){
  if (o && typeof o === 'object' && !Array.isArray(o)) {
    var p = pickM3u8(o, pageUrl);
    if (p) return p;
  }
  if (typeof o === 'string') {
    var mm = o.match(/https?:\/\/\S+?\.m3u8(\?[^\s"']*)?/);
    return mm ? mm[0] : '';
  }
  if (Array.isArray(o)) { for (var i=0;i<o.length;i++){ var r=deepFindM3u8(o[i], pageUrl); if(r) return r; } }
  if (o && typeof o === 'object') { for (var k in o){ var r2=deepFindM3u8(o[k], pageUrl); if(r2) return r2; } }
  return '';
}


// ===== 1. 剧名（h1 优先，title 兜底）=====
var title = '';
var tm = resultStr.match(/<h1[^>]*>([\s\S]*?)<\/h1>/);
if (tm) title = tm[1].replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
if (!title) {
  var tt = resultStr.match(/<title>([\s\S]*?)<\/title>/);
  if (tt) title = tt[1].split('-')[0].trim();
}
if (!title) title = '黄果短剧';

// ===== 2. 从详情页取全部剧集链接（零网络，只解析）=====
var eps = [];
var re = /<a[^>]*href="(\/video\/\d+(?:\/ep-\d+)?\/)"[^>]*>([\s\S]*?)<\/a>/g;
var m2;
while ((m2 = re.exec(resultStr)) !== null) {
  var label = m2[2].replace(/<[^>]+>/g, '').trim();
  if (!label) label = '';
  eps.push({ href: m2[1], label: label });
}
var seenH = {};
var epsU = [];
for (var i = 0; i < eps.length; i++) {
  if (!seenH[eps[i].href]) { seenH[eps[i].href] = 1; epsU.push(eps[i]); }
}
eps = epsU;
if (eps.length === 0) {
  eps.push({ href: '/video/' + (resultStr.match(/\/video\/(\d+)\//) || ['', '0'])[1] + '/', label: '' });
}

// ===== 3. 拼绝对地址数组 =====
var base = String(source.key || '').replace(/#[^\/]*$/, '').replace(/\/+$/, '');
var epUrls = [];
var epLabels = [];
for (var k = 0; k < eps.length; k++) {
  var absUrl = eps[k].href.indexOf('http') === 0 ? eps[k].href : base + eps[k].href;
  epUrls.push(absUrl);
  var num = k + 1;
  var en = eps[k].href.match(/ep-(\d+)/);
  if (en) num = parseInt(en[1], 10);
  epLabels.push(num);
}
var jsonUrls = JSON.stringify(epUrls);
var jsonNums = JSON.stringify(epLabels);
var total = eps.length;

// ===== 4. 只同步取第 1 集（唯一一次规则层网络，秒开不等待全集）=====
// 站点已移除 data-play-src 属性，统一改从 videoInitialData JSON 取 m3u8（兼容旧形态）
var firstSrc = '';
try {
  var fh = java.ajax(epUrls[0]);
  if (fh) {
    firstSrc = extractM3u8FromHtml(String(fh), epUrls[0]);
  }
} catch (e) {}
var jsonFirst = JSON.stringify(firstSrc);var allSrc = [];
try {
  var _vm = resultStr.match(/<script id="videoInitialData" type="application\/json">([\s\S]*?)<\/script>/);
  var curId = _vm ? (JSON.parse(_vm[1]).id) : '';
  if (curId) {
    var _needle = '/video/' + curId + '/';
    var _clean = [];
    for (var _k = 0; _k < epUrls.length; _k++) if (String(epUrls[_k]).indexOf(_needle) >= 0) _clean.push(_k);
    if (_clean.length) {
      var _eu = [], _el = [];
      for (var _c = 0; _c < _clean.length; _c++) { _eu.push(epUrls[_clean[_c]]); _el.push(epLabels[_clean[_c]]); }
      epUrls = _eu; epLabels = _el;
    }
  }
  var _cap = 40;
  for (var _i = 0; _i < epUrls.length && _i < _cap; _i++) {
    var _s = '';
    try { var _fh = java.ajax(epUrls[_i]); if (_fh) _s = extractM3u8FromHtml(String(_fh), epUrls[_i]); } catch (e) {}
    allSrc.push(_s ? _s : '');
  }
} catch (e) {}
if (!allSrc[0] && firstSrc) allSrc[0] = firstSrc;
var jsonAllSrc = JSON.stringify(allSrc);


var S = '<' + 'script>';
var E = '</' + 'script>';

result = `<html>
<head>
<meta name="viewport" content="width=device-width, initial-scale=1">
<style>
*{box-sizing:border-box;-webkit-tap-highlight-color:transparent;margin:0;padding:0}
body{font-family:Arial,sans-serif;background:#0f1115;color:#e8e8e8}
.video-box{width:100%;background:#000;position:relative}
video{width:100%;height:auto;display:block;background:#000;margin:0 auto}
#fr{display:none;position:fixed;top:0;left:0;width:100%;height:100%;border:0;background:#000;z-index:18}
.panel{background:#161a22}
.head{padding:10px 12px 4px}
.title{font-size:16px;font-weight:bold;color:#fff;line-height:1.4;word-break:break-all}
.status{margin-top:5px;font-size:13px;color:#ffb84d;word-break:break-all;min-height:18px}
.eps-wrap{padding:6px 10px 4px}
.eps-hint{font-size:12px;color:#8b93a7;padding:4px}
.eps-grid{display:flex;flex-wrap:wrap;gap:6px;padding:4px}
.ep-btn{min-width:44px;padding:8px 6px;border-radius:6px;border:1px solid #2a3140;background:#1d2330;color:#cfd6e4;font-size:13px;text-align:center;cursor:pointer}
.ep-btn.active{background:#e64c4c;border-color:#e64c4c;color:#fff;font-weight:bold}
.ep-btn.loading{background:#5a4632;border-color:#8a6a3a;color:#ffd9a0}
.nav-row{display:flex;gap:8px;padding:6px 12px 12px}
.nav-btn{flex:1;padding:11px 0;border-radius:8px;border:none;background:#2a3140;color:#e8e8e8;font-size:14px;cursor:pointer}
.nav-btn.primary{background:#e64c4c}
.nav-btn:disabled{opacity:.35;cursor:not-allowed}
.tip{padding:2px 12px 14px;font-size:12px;color:#7a8296;line-height:1.6}
.fbar{display:none;position:fixed;left:0;right:0;bottom:0;z-index:25;background:rgba(12,14,19,.95);padding:8px 10px;gap:8px;align-items:center}
.fbar button{flex:1;min-height:42px;border-radius:8px;border:1px solid #2a3140;background:#1d2330;color:#fff;font-size:15px;cursor:pointer}
.fbar button:disabled{opacity:.35}
#fx{background:#3a2a2a;border-color:#6a3a3a;flex:0 0 74px}
