</style>
</head>
<body>
<div class="video-box">
  <video id="vd" controls playsinline preload="auto"></video>
  <iframe id="fr" sandbox="allow-scripts allow-same-origin allow-presentation" allowfullscreen webkitallowfullscreen></iframe>
</div>
<div class="panel">
  <div class="head">
    <div class="title">` + title + `</div>
    <div class="status" id="st">正在加载第 1 集…</div>
  </div>
  <div class="eps-wrap">
    <div class="eps-hint">第 1 集即开即播；其余集进入后后台自动补齐播放地址，补齐后点集即播（纯视频、无广告）。未补齐时点集会在后台即时抓取。个别抓不到的集可点「网页播放」用官网看（含站内广告）。</div>
    <div class="eps-grid" id="grid"></div>
  </div>
  <div class="nav-row">
    <button class="nav-btn" id="prevBtn">上一集</button>
    <button class="nav-btn primary" id="frameBtn">网页播放</button>
    <button class="nav-btn" id="nextBtn">下一集</button>
  </div>
  <div class="tip">视频顶格满屏，标题在下方选集区。网页模式为该剧官网播放页（已屏蔽弹窗/新窗跳转，但站内横幅广告无法清除，勿点画面以外区域）；底部「返回」可回到本播放器。</div>
</div>
<div class="fbar" id="fbar">
  <button id="fp">上一集</button>
  <span id="ftag">网页播放中</span>
  <button id="fn">下一集</button>
  <button id="fx">返回</button>
</div>

` + S + `
var EP_URLS = ` + jsonUrls + `;
var EP_NUMS = ` + jsonNums + `;
var FIRST_SRC = ` + jsonFirst + `;
var vd = document.getElementById('vd');
var st = document.getElementById('st');
var grid = document.getElementById('grid');
var fr = document.getElementById('fr');
var fbar = document.getElementById('fbar');
var cur = -1;
var mode = 'player';
var btns = [];

// ALL_SRC[i] = 第 i 集播放地址（'' = 未取到）
var ALL_SRC = ` + jsonAllSrc + `;

var deadSet = {};    // 确认抓不到的集（后台不再重试）
var CONC = 3;        // 预载并发路数
var pifs = [];       // 隐藏 iframe 池
var loadingI = -1;   // 点击抢抓中的集

(function(){
  for (var i = 0; i < EP_URLS.length; i++) {
    var b = document.createElement('button');
    b.className = 'ep-btn';
    b.textContent = EP_NUMS[i];
    b.setAttribute('data-i', i);
    b.onclick = function(){ loadEp(parseInt(this.getAttribute('data-i'), 10)); };
    grid.appendChild(b);
    btns.push(b);
  }
})();

function setSt(t){ st.textContent = t; }
function loadedCount(){
  var c = 0;
  for (var i = 0; i < ALL_SRC.length; i++) if (ALL_SRC[i]) c++;
  return c;
}
function updateStatus(){
  if (mode !== 'player') return;
  var lc = loadedCount();
  if (cur >= 0 && ALL_SRC[cur]) {
    setSt('第 ' + EP_NUMS[cur] + ' 集 / 共 ' + EP_URLS.length + ' 集 · 已预载 ' + lc + ' 集');
  } else {
    setSt('后台补齐中：已预载 ' + lc + ' / ' + EP_URLS.length + ' 集');
  }
}
function paint(){
  for (var i = 0; i < btns.length; i++) btns[i].className = 'ep-btn' + (i === cur ? ' active' : '');
  document.getElementById('prevBtn').disabled = (cur <= 0);
  document.getElementById('nextBtn').disabled = (cur >= EP_URLS.length - 1);
}

// 同源读 iframe 内官网集页的播放地址（页面主文档一到即可读，不必等广告脚本加载完）
function pathOf(u){
  var s = String(u || '');
  var i = s.indexOf('://');
  if (i >= 0) {
    s = s.slice(i + 3);
    i = s.indexOf('/');
    if (i < 0) return '/';
    s = s.slice(i);
  }
  var q = s.indexOf('?');
  if (q >= 0) s = s.slice(0, q);
  var h = s.indexOf('#');
  if (h >= 0) s = s.slice(0, h);
  while (s.length > 1 && s.charAt(s.length - 1) === '/') s = s.slice(0, -1);
  return s;
}
function readSrcFromFrame(f, wantUrl){
  try {
    var doc = f.contentDocument;
    if (!doc) return '';
    // URL 守卫：槽换任务导航空窗期 contentDocument 仍是上一任务的残留旧文档——
    // 读到地址前先校验当前文档路径 == 目标任务路径，不一致（残留/中间态）丢弃，继续轮询等新文档
    var du = '';
    try { du = String(doc.URL || (f.contentWindow && f.contentWindow.location && f.contentWindow.location.href) || ''); } catch (e2) { du = ''; }
    if (du && du !== 'about:blank' && wantUrl) {
      if (pathOf(du) !== pathOf(wantUrl)) return '';
    }
    // 站点已移除 data-play-src 属性，统一从 videoInitialData JSON 取；
    // videoSrc=当前集，epPlaySrcs=全剧集表（键"1"恒最前，勿取第一个）
    var vs = null;
    try { vs = doc.getElementById('videoInitialData'); } catch(e){}
    if (vs && vs.textContent) {
      try { var _u = deepFindM3u8(JSON.parse(vs.textContent), wantUrl); if (_u) return _u; } catch(e){}
    }
    var html = '';
    try { html = doc.documentElement ? doc.documentElement.outerHTML : (doc.body ? doc.body.innerHTML : ''); } catch(e){}
    if (html) { var _u2 = extractM3u8FromHtml(html, wantUrl); if (_u2) return _u2; }
  } catch (e) {}
  return '';
}
// iframe 池管理（不用 display:none，改用 2px 透明占位——避免部分 WebView 对 display:none iframe 的加载节流）
function makeSlot(){
  var f = document.createElement('iframe');
  f.setAttribute('sandbox', 'allow-scripts allow-same-origin');
  f.style.cssText = 'position:fixed;left:0;top:0;width:2px;height:2px;border:0;opacity:0.02;z-index:-1;background:transparent;';
  document.body.appendChild(f);
  var slot = { f: f, busy: false, tok: 0, i: -1, st: 0 };
  pifs.push(slot);
  return slot;
}
function freeSlot(){
  for (var i = 0; i < pifs.length; i++) if (!pifs[i].busy) return pifs[i];
  return null;
}
function oldestBusy(){
  var o = null;
  for (var i = 0; i < pifs.length; i++) {
    if (pifs[i].busy && (!o || pifs[i].st < o.st)) o = pifs[i];
  }
  return o;
}
function isFetching(i){
  for (var x = 0; x < pifs.length; x++) if (pifs[x].busy && pifs[x].i === i) return true;
  return false;
}

// 在槽上抓第 i 集：500ms 轮询早读 src（不等 onload），读到即完成；onload 兜底；30s 超时
function startJob(slot, i, done, urgent){
  var f = slot.f;
  var myTok = ++slot.tok;
  slot.busy = true;
  slot.i = i;
  slot.st = Date.now();
  var finished = false;
  var tries = 0;
  var pollId = null, toId = null;
  function finish(ok){
    if (finished) return;
    finished = true;
    if (pollId) clearInterval(pollId);
    if (toId) clearTimeout(toId);
    f.onload = null; f.onerror = null;
    if (slot.tok !== myTok) return;   // 已被点击抢占，槽归新任务
    slot.busy = false; slot.i = -1;
    if (ok) ALL_SRC[i] = ok;
    else if (!urgent) deadSet[i] = true;
    updateStatus();
    if (done) done(ok);
    setTimeout(prefetchTick, 60);
  }
  pollId = setInterval(function(){
    if (slot.tok !== myTok) { clearInterval(pollId); return; }
    tries++;
    var u = readSrcFromFrame(f, EP_URLS[i]);
    if (u) { finish(u); return; }
    if (tries >= 60) finish('');   // 约 30s 仍读不到
  }, 500);
  toId = setTimeout(function(){ finish(''); }, 30000);
  f.onload = function(){ if (slot.tok === myTok) { var u = readSrcFromFrame(f, EP_URLS[i]); finish(u); } };
  f.onerror = function(){ if (slot.tok === myTok) finish(''); };
  f.src = EP_URLS[i];
}

// 抓第 i 集。urgent=true（点击）无空槽时抢占最久后台任务
function jobEp(i, done, urgent){
  var slot;
  if (urgent) {
    slot = freeSlot();
    if (!slot) slot = oldestBusy();
    if (!slot && pifs.length < CONC) slot = makeSlot();
  } else {
    slot = freeSlot();
    if (!slot && pifs.length < CONC) slot = makeSlot();
  }
  if (!slot) return false;
  startJob(slot, i, done, urgent);
  return true;
}

// 找下一个未取的集（0..cap）
function nextPending(cap){
  for (var i = 0; i < cap; i++) {
    if (!ALL_SRC[i] && !deadSet[i]) return i;
  }
  return -1;
}

// 后台补齐：并发派发到池满；槽释放回调自动续
function prefetchTick(){
  if (mode === 'frame') return;
  var cap = EP_URLS.length; if (cap > 15) cap = 15;
  for (;;) {
    var i = nextPending(cap);
    if (i < 0) { updateStatus(); return; }
    if (!jobEp(i, null, false)) return;   // 池满，等释放回调再续
  }
}

// 进入网页模式（官网播放器；sandbox 已禁弹窗/顶层跳转）
function enterFrame(i, why){
  if (i < 0 || i >= EP_URLS.length) return;
  cur = i;
  mode = 'frame';
  try { vd.pause(); vd.removeAttribute('src'); vd.load(); } catch (e) {}
  fr.src = EP_URLS[i];
  fr.style.display = 'block';
  fbar.style.display = 'flex';
  document.getElementById('fp').disabled = (cur <= 0);
  document.getElementById('fn').disabled = (cur >= EP_URLS.length - 1);
  setSt((why ? '[官网播放] ' + why : '官网播放中') + ' · 第 ' + EP_NUMS[i] + ' 集');
  paint();
}
function exitFrame(){
  mode = 'player';
  fr.src = 'about:blank';
  fr.style.display = 'none';
  fbar.style.display = 'none';
  loadEp(cur >= 0 ? cur : 0);
  setTimeout(prefetchTick, 200);
}

// 播放：canplay/loadeddata 一次性兜底自动播（修复切集后停在暂停态需手点播放键）
var playOnce = null;
function playSrc(u, i){
  if (mode !== 'player') return;
  if (playOnce) {
    vd.removeEventListener('canplay', playOnce);
    vd.removeEventListener('loadeddata', playOnce);
    playOnce = null;
  }
  playOnce = function(){
    if (playOnce) { vd.removeEventListener('canplay', playOnce); vd.removeEventListener('loadeddata', playOnce); playOnce = null; }
    var p = vd.play();
    if (p && p.catch) p.catch(function(){});
  };
  vd.addEventListener('canplay', playOnce);
  vd.addEventListener('loadeddata', playOnce);
  vd.src = u;
  vd.load();
  setSt('第 ' + EP_NUMS[i] + ' 集 / 共 ' + EP_URLS.length + ' 集');
  paint();
  var p = vd.play();
  if (p && p.catch) p.catch(function(){});
}

// 选集：地址在手即播；否则即时抢抓（打断最久的后台任务，完成自动续后台队列）
function loadEp(i){
  if (i < 0 || i >= EP_URLS.length) return;
  if (mode === 'frame') { enterFrame(i, ''); return; }
  cur = i;
  paint();
  if (ALL_SRC[i]) { playSrc(ALL_SRC[i], i); return; }
  if (deadSet[i]) { enterFrame(i, '该集取源失败'); return; }
  if (isFetching(i)) { setSt('正在获取第 ' + EP_NUMS[i] + ' 集播放地址…'); return; }
  setSt('正在获取第 ' + EP_NUMS[i] + ' 集播放地址…');
  var assigned = jobEp(i, function(ok){
    if (cur !== i || mode !== 'player') return;
    if (ok) playSrc(ALL_SRC[i], i); else enterFrame(i, '该集取源失败');
  }, true);
  if (!assigned) {
    setTimeout(function(){ if (cur === i && mode === 'player') loadEp(i); }, 150);
  }
}

document.getElementById('prevBtn').onclick = function(){ if (cur > 0) loadEp(cur - 1); };
document.getElementById('nextBtn').onclick = function(){ if (cur < EP_URLS.length - 1) loadEp(cur + 1); };
document.getElementById('frameBtn').onclick = function(){
  if (mode === 'frame') { exitFrame(); }
  else { enterFrame(cur >= 0 ? cur : 0, '手动切换'); }
};
document.getElementById('fp').onclick = function(){ if (cur > 0) { if (mode === 'frame') enterFrame(cur - 1, ''); else loadEp(cur - 1); } };
document.getElementById('fn').onclick = function(){ if (cur < EP_URLS.length - 1) { if (mode === 'frame') enterFrame(cur + 1, ''); else loadEp(cur + 1); } };
document.getElementById('fx').onclick = exitFrame;

// 竖屏/超高视频不超屏
(function(){
  function fit(){
    var vw = vd.videoWidth || 16, vh = vd.videoHeight || 9;
    var maxH = Math.round(window.innerHeight * 0.94);
    var w = vd.clientWidth || 320;
    var h = w * vh / vw;
    if (h > maxH) {
      vd.style.height = maxH + 'px';
      vd.style.width = 'auto';
      vd.style.margin = '0 auto';
    } else {
      vd.style.height = 'auto';
      vd.style.width = '100%';
      vd.style.margin = '0 auto';
    }
  }
  vd.addEventListener('loadedmetadata', fit);
  window.addEventListener('resize', fit);
  window.addEventListener('orientationchange', function(){ setTimeout(fit, 300); });
})();

// 滑动快进手势
(function(){
  var sx = 0, sy = 0, t0 = 0, lp = false;
  vd.addEventListener('touchstart', function(e){
    sx = e.touches[0].clientX; sy = e.touches[0].clientY; t0 = Date.now(); lp = false;
  }, {passive:true});
  vd.addEventListener('touchmove', function(e){
